 archive. It is not a new historical delivery certificate.", "versionLabel": "replay-v01", "rights": "Private rehearsal. Original distribution rights to document.", "ai": "Not documented"}}]}'::jsonb; p jsonb; r jsonb; author_record record;
BEGIN
IF (SELECT count(*) FROM bee_community_members m JOIN bee_community_users u ON u.id=m.user_id WHERE m.project_id='b0000000-0000-4000-8000-000000000001' AND u.is_test AND NOT u.disabled) <> 11 THEN RAISE EXCEPTION 'Expected existing 11 test members'; END IF;
FOR p IN SELECT * FROM jsonb_array_elements(payload->'projects') LOOP
 IF EXISTS(SELECT 1 FROM bee_community_projects WHERE id=(p->>'id')::uuid AND NOT is_demo) THEN RAISE EXCEPTION 'Non-demo target'; END IF;
 INSERT INTO bee_community_projects(id,title,territory,season,is_demo) VALUES((p->>'id')::uuid,p->>'title',p->>'territory','Replay · '||(p->>'stage'),true) ON CONFLICT(id) DO NOTHING;
 INSERT INTO bee_community_members(project_id,user_id,role) SELECT (p->>'id')::uuid,m.user_id,m.role FROM bee_community_members m JOIN bee_community_users u ON u.id=m.user_id WHERE m.project_id='b0000000-0000-4000-8000-000000000001' AND u.is_test AND NOT u.disabled ON CONFLICT DO NOTHING;
END LOOP;
FOR r IN SELECT * FROM jsonb_array_elements(payload->'records') LOOP
 SELECT u.id,u.organization INTO author_record FROM bee_community_members m JOIN bee_community_users u ON u.id=m.user_id WHERE m.project_id=(r->>'project_id')::uuid AND m.role=r->>'role' AND u.is_test AND NOT u.disabled ORDER BY u.id LIMIT 1;
 WITH inserted AS (INSERT INTO bee_community_records(id,project_id,kind,title,status,data,organization,created_by) VALUES((r->>'id')::uuid,(r->>'project_id')::uuid,r->>'kind',r->>'title',r->>'status',r->'data',author_record.organization,author_record.id) ON CONFLICT(id) DO NOTHING RETURNING id)
 INSERT INTO bee_community_events(id,project_id,record_id,actor_id,action,new_state,comment) SELECT gen_random_uuid(),(r->>'project_id')::uuid,id,author_record.id,'replay_initialized',r->>'status','Pedagogical starting state. Real campaign references; synthetic workflow, no historical approval or impact claim.' FROM inserted;
END LOOP;
END $seed$;
COMMIT;
SELECT json_build_object('projects',count(*),'demo_only',bool_and(is_demo)) FROM bee_community_projects WHERE id IN ('b0000000-0000-4000-8000-000000000101'::uuid,'b0000000-0000-4000-8000-000000000102'::uuid,'b0000000-0000-4000-8000-000000000103'::uuid,'b0000000-0000-4000-8000-000000000104'::uuid,'b0000000-0000-4000-8000-000000000105'::uuid);
